BEGIN;
CREATE SCHEMA IF NOT EXISTS burgoweb_global;
CREATE TABLE IF NOT EXISTS burgoweb_global.accounts (id uuid PRIMARY KEY, email_normalized text NOT NULL UNIQUE, state text NOT NULL CHECK (state IN ('pending_verification','disabled')), created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS burgoweb_global.credentials (account_id uuid PRIMARY KEY REFERENCES burgoweb_global.accounts(id), encoded_hash text NOT NULL, pepper_version text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS burgoweb_global.tenant_registry (id uuid PRIMARY KEY, public_id uuid NOT NULL UNIQUE, schema_name text NOT NULL UNIQUE CHECK (schema_name ~ '^tenant_[a-f0-9]{32}$'), display_name text NOT NULL, state text NOT NULL CHECK (state IN ('provisioning','pending_verification','quarantined','compensated')), migration_version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS burgoweb_global.provisioning_requests (id uuid PRIMARY KEY, account_id uuid REFERENCES burgoweb_global.accounts(id), tenant_id uuid REFERENCES burgoweb_global.tenant_registry(id), state text NOT NULL CHECK (state IN ('processing','pending_verification','compensated','quarantined','conflict')), correlation_id uuid NOT NULL, diagnostic_code text, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS burgoweb_global.authority_declarations (id uuid PRIMARY KEY, request_id uuid NOT NULL REFERENCES burgoweb_global.provisioning_requests(id), account_id uuid NOT NULL REFERENCES burgoweb_global.accounts(id), tenant_id uuid NOT NULL REFERENCES burgoweb_global.tenant_registry(id), declarant_name text NOT NULL, declaration_text text NOT NULL, declaration_version text NOT NULL, accepted_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS burgoweb_global.pending_authorities (id uuid PRIMARY KEY, request_id uuid NOT NULL REFERENCES burgoweb_global.provisioning_requests(id), tenant_id uuid NOT NULL REFERENCES burgoweb_global.tenant_registry(id), account_id uuid NOT NULL REFERENCES burgoweb_global.accounts(id), state text NOT NULL CHECK (state = 'pending_verification'));
CREATE TABLE IF NOT EXISTS burgoweb_global.idempotency_records (operation text NOT NULL, idempotency_key text NOT NULL, request_hash char(64) NOT NULL, request_id uuid NOT NULL REFERENCES burgoweb_global.provisioning_requests(id), response_json jsonb, PRIMARY KEY (operation, idempotency_key));
CREATE TABLE IF NOT EXISTS burgoweb_global.audit_events (id uuid PRIMARY KEY, request_id uuid NOT NULL, event_type text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL);
COMMIT;
